from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urljoin,urlsplit
import hashlib,json,re
base='https://dext.com/ca'
src=Path('products/services/invoice-export-qa-alternative/raw/dext-canada.html')
raw=src.read_bytes()
class Page(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.skip=set(); self.parts=[]; self.links=[]; self.anchor=None
    def handle_starttag(self,tag,attrs):
        attrs=dict(attrs)
        if tag in {'script','style','template'}: self.skip.add(tag)
        if tag=='a' and attrs.get('href') and not self.skip: self.anchor=(attrs['href'],[])
    def handle_endtag(self,tag):
        self.skip.discard(tag)
        if tag=='a' and self.anchor:
            href,parts=self.anchor
            if href.startswith(('https://','/')):
                url=urljoin(base,href)
                if urlsplit(url).hostname in {'dext.com','www.dext.com','help.dext.com'}: self.links.append({'label':' '.join(parts),'url':url})
            self.anchor=None
    def handle_data(self,text):
        text=' '.join(text.split())
        if self.skip or not text: return
        self.parts.append(text)
        if self.anchor: self.anchor[1].append(text)
page=Page(); page.feed(raw.decode('utf-8',errors='replace'))
pattern=re.compile(r'\b(?:exports?|exporting|download|csv|line items?|subtotal|purchase invoices?)\b',re.I)
text=' '.join(page.parts)
excerpts=[text[max(0,m.start()-100):m.end()+125] for m in list(pattern.finditer(text))[:24]]
links=[link for link in page.links if pattern.search(link['label']+' '+urlsplit(link['url']).path)]
result={'source':base,'sha256':hashlib.sha256(raw).hexdigest(),'visible_text_excerpts':list(dict.fromkeys(excerpts)),'linked_page_pointers':list({link['url']:link for link in links}.values())[:15],'scope':'Navigation pointers from saved public HTML. A keyword match or absence does not establish export fields, feature coverage, buyer demand, or permission to contact.'}
out=src.parent.parent/'director-dext-workflow-pointers.json'
out.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(out.read_text(encoding='utf-8'))
